from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]


def require_local_smoke(script_name: str) -> None:
    """Run a local smoke script from the repository root."""
    try:
        subprocess.run(
            [sys.executable, str(ROOT / "scripts" / script_name)],
            cwd=ROOT,
            check=True,
            text=True,
        )
    except subprocess.CalledProcessError as exc:
        fail(f"{script_name} failed with exit code {exc.returncode}")

