def fail(message: str) -> None:
    raise SystemExit(f"MAINLINE_GUARD: FAIL: {message}")


def require_files() -> None:
    missing = [path for path in REQUIRED_FILES if not (ROOT / path).is_file()]
    if missing:
        fail("missing files: " + ", ".join(missing))


def require_dirs() -> None:
    missing = [path for path in REQUIRED_SUBSYSTEM_DIRS if not (ROOT / path).is_dir()]
    if missing:
        fail("missing subsystem dirs: " + ", ".join(missing))


def require_phrases() -> None:
    for relpath, phrases in REQUIRED_PHRASES.items():
        text = (ROOT / relpath).read_text(encoding="utf-8")
        missing = [phrase for phrase in phrases if phrase not in text]
        if missing:
            fail(f"{relpath} missing phrases: {', '.join(missing)}")


