def require_agent_index_alignment() -> None:
    index = json.loads((ROOT / "agent-index.json").read_text(encoding="utf-8"))
    subsystems = index.get("subsystems", {})
    missing = [path for path in REQUIRED_SUBSYSTEM_DIRS if path not in subsystems]
    if missing:
        fail("agent-index.json missing subsystem keys: " + ", ".join(missing))


def require_experiment_config() -> None:
    config_path = ROOT / "saee_experiments/configs/experiment_config.yaml"
    values: dict[str, str] = {}
    for line in config_path.read_text(encoding="utf-8").splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        if ":" not in stripped:
            fail(f"experiment_config.yaml invalid line: {line}")
        key, value = stripped.split(":", 1)
        values[key.strip()] = value.strip()
    required = {
        "generation_count",
        "population_size",
        "deterministic_seed",
        "logging_level",
        "seed_path",
        "output_dir",
    }
    missing = required - set(values)
    if missing:
        fail("experiment_config.yaml missing keys: " + ", ".join(sorted(missing)))
    generation_count = int(values["generation_count"])
    if generation_count < 100 or generation_count > 10000:
        fail("experiment_config.yaml generation_count outside 100..10000")
    if values["deterministic_seed"] != "enabled":
        fail("experiment_config.yaml deterministic_seed must be enabled")
    if values["logging_level"] != "full_trace":
        fail("experiment_config.yaml logging_level must be full_trace")


