    agent_index = json.loads((ROOT / "agent-index.json").read_text(encoding="utf-8"))
    entry = agent_index.get("tenant_storage_remaining_gap_packet_v0_1", {})
    for flag, expected_value in expected_payload.items():
        if entry.get(flag) != expected_value:
            fail(
                "agent-index.json tenant_storage_remaining_gap_packet_v0_1 "
                f"{flag} must be {expected_value}"
            )
    for flag in false_flags:
        if entry.get(flag) is not False:
            fail(
                "agent-index.json tenant_storage_remaining_gap_packet_v0_1 "
                f"{flag} must be false"
            )
    if entry.get("remaining_missing_evidence_keys") != expected_missing:
        fail("agent-index tenant storage remaining gap keys changed")
    if entry.get("make_target") != "make check-tenant-storage-remaining-gap-packet":
        fail("agent-index tenant storage remaining gap make_target changed")


