def require_first_user_test_boundary() -> None:
    files = [
        ROOT / "docs/strategy/SAEE_FIRST_USER_TEST_RECOMMENDATION_GATE.md",
        ROOT / "phase_b_product/validation/README.md",
        ROOT / "phase_b_product/validation/SAEE_FIRST_USER_TEST_PLAN.md",
        ROOT / "phase_b_product/validation/FIRST_USER_FEEDBACK_FORM.md",
        ROOT / "phase_b_product/validation/FIRST_USER_SUCCESS_CRITERIA.md",
    ]
    required_tokens = [
        "customer_validated: false",
        "product_launched: false",
        "production_deployed: false",
        "public_sdk_release: false",
        "user_upload_enabled: false",
        "private_core_exported: false",
        "implementation_disclosed: false",
    ]
    forbidden_tokens = [
        "customer_validated: true",
        "product_launched: true",
        "production_deployed: true",
        "public_sdk_release: true",
        "user_upload_enabled: true",
        "private_core_exported: true",
        "api_contract_modified: true",
        "api_schema_modified: true",
        "landing_page_modified: true",
        "decision_engine_modified: true",
        "saee_v1_0/kernel",
        "kernel/runtime.py",
        "selection_engine",
        "mutation_engine",
        "lineage_engine",
        "fitness_engine",
    ]
    for path in files:
        text = path.read_text(encoding="utf-8")
        missing = [token for token in required_tokens if token not in text]
        if missing:
            relpath = path.relative_to(ROOT)
            fail(f"{relpath} missing first-user-test boundary tokens: {', '.join(missing)}")
        found = [token for token in forbidden_tokens if token in text]
        if found:
            relpath = path.relative_to(ROOT)
            fail(f"{relpath} contains forbidden first-user-test tokens: {', '.join(found)}")


