def require_agent_recommendation_surface_boundary() -> None:
    recommendation_files = [
        ROOT / "docs/strategy/SAEE_AGENT_RECOMMENDATION_SURFACE_RECOMMENDATION_GATE.md",
        ROOT / "agent_recommendation/PRODUCT_FACTS.md",
        ROOT / "agent_recommendation/PRODUCT_FACTS.json",
        ROOT / "agent_recommendation/WHEN_TO_RECOMMEND_SAEE.md",
        ROOT / "agent_recommendation/WHEN_NOT_TO_RECOMMEND_SAEE.md",
        ROOT / "agent_recommendation/SAEE_VS_EXISTING_TOOLS.md",
        ROOT / "agent_recommendation/TARGET_USER_PROFILES.md",
        ROOT / "agent_recommendation/BUYER_QUESTIONS_AND_ANSWERS.md",
        ROOT / "agent_recommendation/RECOMMENDATION_DECISION_TREE.md",
        ROOT / "agent_recommendation/EVIDENCE_SUMMARY.md",
        ROOT / "agent_recommendation/INTEGRATION_PATHS.md",
        ROOT / "agent_recommendation/AGENT_RECOMMENDATION_FIT.md",
        ROOT / "agent_recommendation/AGENT_RECOMMENDATION_TEST_SET.json",
        ROOT / "phase_b_product/landing/for-ai-assistants.html",
    ]
    combined = "\n".join(path.read_text(encoding="utf-8") for path in recommendation_files)
    forbidden_tokens = [
        "saee_v1_0/kernel",
        "kernel/runtime.py",
        "fitness_engine",
        "selection_engine",
        "mutation_engine",
        "lineage_engine",
        "runtime_v1_0",
        "private production evaluator",
        "product_launched: true",
        "production_deployed: true",
        "public_sdk_release: true",
        "customer_validated: true",
        "user_upload_enabled: true",
        "private_core_exported: true",
    ]
    found = [token for token in forbidden_tokens if token in combined]
    if found:
        fail("agent recommendation surface contains forbidden tokens: " + ", ".join(found))

    llms = (ROOT / "llms.txt").read_text(encoding="utf-8")
    required_llms_paths = [
        "/agent_recommendation/PRODUCT_FACTS.md",
        "/agent_recommendation/WHEN_TO_RECOMMEND_SAEE.md",
        "/agent_recommendation/WHEN_NOT_TO_RECOMMEND_SAEE.md",
        "/agent_recommendation/RECOMMENDATION_DECISION_TREE.md",
        "/agent_recommendation/BUYER_QUESTIONS_AND_ANSWERS.md",
        "/phase_b_product/landing/for-ai-assistants.html",
    ]
    missing_llms = [path for path in required_llms_paths if path not in llms]
    if missing_llms:
        fail("llms.txt missing agent recommendation paths: " + ", ".join(missing_llms))

    facts = json.loads((ROOT / "agent_recommendation/PRODUCT_FACTS.json").read_text(encoding="utf-8"))
    current = facts.get("current_status", {})
    expected_false = [
        "production_ready",
        "customer_validated",
        "customer_contacted",
        "public_sdk_released",
        "product_launched",
        "user_upload_enabled",
        "private_core_exposed",
    ]
    bad_current = [flag for flag in expected_false if current.get(flag) is not False]
    if bad_current:
        fail("PRODUCT_FACTS.json current_status flags must remain false: " + ", ".join(bad_current))

    test_cases = json.loads(
        (ROOT / "agent_recommendation/AGENT_RECOMMENDATION_TEST_SET.json").read_text(encoding="utf-8")
    )
    actions = [case.get("expected_action") for case in test_cases]
    if len(test_cases) < 20:
        fail("AGENT_RECOMMENDATION_TEST_SET.json must contain at least 20 cases")
    if actions.count("recommend") < 8:
        fail("AGENT_RECOMMENDATION_TEST_SET.json must contain at least 8 recommend cases")
    if actions.count("do_not_recommend") < 8:
        fail("AGENT_RECOMMENDATION_TEST_SET.json must contain at least 8 do_not_recommend cases")
    if actions.count("mention") < 4:
        fail("AGENT_RECOMMENDATION_TEST_SET.json must contain at least 4 mention cases")

    assistant_page = (ROOT / "phase_b_product/landing/for-ai-assistants.html").read_text(encoding="utf-8")
    if "<script" in assistant_page.lower() or "fetch(" in assistant_page:
        fail("phase_b_product/landing/for-ai-assistants.html must remain static with no backend calls")


