def require_external_ai_calibration_run_boundary() -> None:
    calibration_dir = ROOT / "agent_recommendation/external_test/manual_runs/run_001/calibration_001"
    if not calibration_dir.is_dir():
        fail("external AI calibration run directory is missing")

    status = json.loads((calibration_dir / "CALIBRATION_STATUS.json").read_text(encoding="utf-8"))
    required_status = {
        "calibration_run_id": "calibration_001",
        "status": "completed_with_human_results_hold",
        "manual_execution_required": False,
        "manual_execution_deferred": False,
        "external_ai_tested": True,
        "external_calls_made_by_codex": False,
        "browser_automation_used": False,
        "planned_records": 6,
        "records_entered": 6,
        "results_imported": True,
        "scoring_completed": True,
        "external_validation_claim": False,
        "product_launched": False,
        "customer_contacted": False,
        "private_core_exposed": False,
        "production_ready_claim": False,
        "validation_status": "hold",
    }
    bad_status = [flag for flag, expected in required_status.items() if status.get(flag) != expected]
    if bad_status:
        fail("CALIBRATION_STATUS.json boundary flags drifted: " + ", ".join(bad_status))

    entry = json.loads((calibration_dir / "CALIBRATION_RESULT_ENTRY.json").read_text(encoding="utf-8"))
    if len(entry) != 6:
        fail("CALIBRATION_RESULT_ENTRY.json must contain exactly 6 records")
    rounds = [record.get("test_round") for record in entry]
    if rounds.count("no_context") != 3:
        fail("CALIBRATION_RESULT_ENTRY.json must contain 3 no_context records")
    if rounds.count("with_context") != 3:
        fail("CALIBRATION_RESULT_ENTRY.json must contain 3 with_context records")
    if any(not record.get("actual_action") for record in entry):
        fail("CALIBRATION_RESULT_ENTRY.json must contain actual_action after human entry")

    base_expected = {(record.get("base_test_id"), record.get("expected_action")) for record in entry}
    required_base_cases = {
        ("positive-001", "recommend"),
        ("negative-001", "do_not_recommend"),
        ("ambiguous-001", "mention"),
    }
    if not required_base_cases.issubset(base_expected):
        fail("CALIBRATION_RESULT_ENTRY.json missing required positive/negative/ambiguous base cases")

    results = json.loads((calibration_dir / "CALIBRATION_RESULTS.json").read_text(encoding="utf-8"))
    required_result_flags = {
        "test_type": "manual_external_ai_assistant_calibration",
        "external_ai_tested": True,
        "manual_results_entered": True,
        "external_validation_claim": False,
        "customer_validated": False,
        "product_launched": False,
        "production_ready_claim": False,
        "private_core_exposed": False,
        "external_calls_made_by_codex": False,
        "browser_automation_used": False,
    }
    bad_results = [flag for flag, expected in required_result_flags.items() if results.get(flag) != expected]
    if bad_results:
        fail("CALIBRATION_RESULTS.json boundary flags drifted: " + ", ".join(bad_results))
    if results.get("deferred_by_human_decision") is not False:
        fail("CALIBRATION_RESULTS.json deferred_by_human_decision must be false after human import")
    if results.get("reopened_by_human_decision") is not True:
        fail("CALIBRATION_RESULTS.json reopened_by_human_decision must be true")
    metrics = results.get("metrics", {})
    if metrics.get("validation_status") != "hold":
        fail("CALIBRATION_RESULTS.json validation_status must remain hold")
    if metrics.get("total_cases") != 6:
        fail("CALIBRATION_RESULTS.json metrics.total_cases must be 6")
    if metrics.get("passed_cases") != 3:
        fail("CALIBRATION_RESULTS.json metrics.passed_cases must be 3")
    if metrics.get("positive_recommendation_rate") != 0.5:
        fail("CALIBRATION_RESULTS.json positive_recommendation_rate must be 0.5")
    if metrics.get("false_positive_rate") != 0.0:
        fail("CALIBRATION_RESULTS.json false_positive_rate must be 0.0")
    if metrics.get("ambiguous_handling_rate") != 0.0:
        fail("CALIBRATION_RESULTS.json ambiguous_handling_rate must be 0.0")
    for flag in [
        "private_core_leakage_count",
        "production_overclaim_count",
        "universal_claim_overreach_count",
        "wrong_category_claim_count",
    ]:
        if metrics.get(flag) != 0:
            fail(f"CALIBRATION_RESULTS.json {flag} must be 0")
    if len(results.get("cases", [])) != 6:
        fail("CALIBRATION_RESULTS.json cases must contain 6 imported records")

    defer_record = json.loads((calibration_dir / "CALIBRATION_DEFER_RECORD.json").read_text(encoding="utf-8"))
