    if summary.get("run_type") != "one_time_read_only_public_signal_collection":
        fail("SIGNAL_SUMMARY.json run_type must be one_time_read_only_public_signal_collection")
    if summary.get("candidate_source") != "SI-004":
        fail("SIGNAL_SUMMARY.json candidate_source must remain SI-004")
    if summary.get("human_review_decision") != "conditional_approve":
        fail("SIGNAL_SUMMARY.json human_review_decision must remain conditional_approve")

    required_summary_flags = {
        "external_model_api_called": False,
        "external_ai_assistant_tested": False,
        "runtime_modified": False,
        "backend_modified": False,
        "kernel_modified": False,
        "api_schema_modified": False,
        "private_core_exposed": False,
        "product_launched": False,
        "customer_contacted": False,
        "task_candidates_executed": False,
        "human_review_required": True,
    }
    bad_flags = [flag for flag, expected in required_summary_flags.items() if summary.get(flag) is not expected]
    if bad_flags:
        fail("SIGNAL_SUMMARY.json boundary flags drifted: " + ", ".join(bad_flags))

    if summary.get("run_status") not in {"pass", "hold", "stop"}:
        fail("SIGNAL_SUMMARY.json run_status must be pass, hold, or stop")
    if summary.get("network_available") is True and summary.get("source_count", 0) < 8:
        fail("SIGNAL_SUMMARY.json network_available=true requires at least 8 sources")
    if summary.get("source_count") != len(summary.get("sources", [])):
        fail("SIGNAL_SUMMARY.json source_count must match sources length")

    scores = summary.get("scores", {})
    for key in ["signal_relevance", "competitor_specificity", "commercial_actionability", "boundary_safety"]:
        score = scores.get(key)
        if not isinstance(score, int) or not 0 <= score <= 5:
            fail(f"SIGNAL_SUMMARY.json score {key} must be integer 0-5")
    if scores.get("boundary_safety") != 5:
        fail("SIGNAL_SUMMARY.json boundary_safety must remain 5")

    allowed_candidate_types = {
        "messaging_update",
        "recommendation_material_update",
        "landing_copy_review",
        "pricing_packaging_review",
        "competitor_positioning_note",
        "external_test_prompt_update",
    }
