def require_tenant_secret_boundary() -> None:
    require_local_smoke("saee_tenant_secret_boundary_profile_smoke.py")
    doc = (
        ROOT / "phase_b_product/commercial_readiness/TENANT_SECRET_BOUNDARY_V0_1.md"
    ).read_text(encoding="utf-8")
    gate = (
        ROOT / "docs/strategy/SAEE_TENANT_SECRET_BOUNDARY_RECOMMENDATION_GATE.md"
    ).read_text(encoding="utf-8")
    profile = json.loads(
        (
            ROOT
            / "phase_b_product/commercial_readiness/tenant_secret_boundary/tenant_secret_boundary.local.json"
        ).read_text(encoding="utf-8")
    )
    validation = json.loads(
        (
            ROOT
            / "agent_recommendation/tenant_secret_boundary/run_001/independent_agent_validation.local.json"
        ).read_text(encoding="utf-8")
    )
    for text, token in (
        (doc, "tenant_secret_boundary_v0_1: true"),
        (doc, "production_tenant_secret_boundary_reviewed: false"),
        (gate, "answer: recommend"),
        (gate, "development_blockers_before_fix: 4"),
        (gate, "tenant_secret_boundary_reviewed: false"),
    ):
        if token not in text:
            fail("tenant secret boundary missing token: " + token)
    if profile.get("negative_cases_passed") != profile.get("negative_cases_total") or profile.get(
        "negative_cases_total"
    ) != 24:
        fail("tenant secret boundary negative cases must be 24/24")
    for key in (
        "audit_closed_schema",
        "request_secret_input_rejected",
        "runner_revalidation",
        "persistence_closed_schema",
        "memory_copy_isolation",
        "sqlite_tenant_key_pseudonymous",
        "legacy_raw_tenant_key_fail_closed",
        "audit_route_template_only",
        "raw_tenant_cross_field_denied",
        "nested_type_fail_closed",
    ):
        if profile.get(key) is not True:
            fail("tenant secret boundary true flag missing: " + key)
    for key in (
        "automatic_legacy_migration_performed",
        "tenant_secret_boundary_reviewed",
        "production_secrets_management_available",
        "encryption_at_rest_proven",
        "kms_hsm_available",
        "tenant_authorization_enabled",
        "production_tenant_storage_isolated",
        "security_review_completed",
        "privacy_legal_review_completed",
        "customer_validated",
        "production_ready",
        "product_launched",
    ):
        if profile.get(key) is not False:
            fail("tenant secret boundary false flag drift: " + key)
    if profile.get("blockers_closed") != 0 or profile.get("secret_echo_count") != 0:
        fail("tenant secret boundary zero-effect drift")
    if (
        validation.get("verdict") != "recommend"
        or validation.get("round_4", {}).get("blocker_count") != 0
        or validation.get("negative_cases_passed") != 24
        or validation.get("negative_cases_total") != 24
        or validation.get("tenant_secret_boundary_reviewed") is not False
        or validation.get("production_ready") is not False
        or validation.get("blockers_closed_by_validation") != 0
    ):
        fail("tenant secret boundary independent agent validation drift")
    for rel, expected in profile.get("source_sha256", {}).items():
        actual = hashlib.sha256((ROOT / rel).read_bytes()).hexdigest()
        if actual != expected:
            fail("tenant secret boundary source hash drift: " + rel)


